const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const source='https://normograma.dian.gov.co/dian/compilacion/docs/decreto_1881_2021.htm';
const arancel='https://muisca.dian.gov.co/WebArancel/DefMenuConsultas.faces';
const alphabet='https://importacionescarga.dian.gov.co/WebArancel/DefMenuConsultasTexto.faces';
const vuce='https://www.vuce.gov.co/servicios/importaciones/importaciones-vuce-2-0';
const external=(url,title)=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(title)} <span aria-hidden="true">↗</span></a>`;
const reference=(id,title)=>`<button data-open="${id}">${escape(title)} <span aria-hidden="true">↗</span></button>`;
const queryButton=(q,label)=>`<button data-query="${escape(q)}">${escape(label||q)} <span aria-hidden="true">→</span></button>`;
const prettyTitle=s=>s===s.toUpperCase()?s.charAt(0)+s.slice(1).toLowerCase():s;
const codeLabel=code=>code.length===2?`Capítulo ${code}`:code.length===4?`Partida ${code.slice(0,2)}.${code.slice(2)}`:`Subpartida SA ${code.slice(0,4)}.${code.slice(4)}`;

function candidateCard(c){const long=c.title.length>190;return `<article class="tariff-candidate"><div class="tariff-code">${escape(codeLabel(c.code))}</div>${c.code.length>2?`<p class="chapter-context">Capítulo ${c.chapter} · ${escape(prettyTitle(c.chapterTitle))}</p>`:''}<h3>${escape(prettyTitle(long?c.title.slice(0,180).replace(/\s+\S*$/,'')+'…':c.title))}</h3>${long?`<details class="tariff-description"><summary>Descripción completa</summary><p>${escape(c.title)}</p></details>`:''}${c.heading&&/^(los demas|las demas|otros|otras)$/i.test(c.title)?`<p class="chapter-context">Dentro de: ${escape(c.heading)}</p>`:''}<div class="candidate-links">${external(arancel,'Verificar en la DIAN')}${queryButton(c.code,'Consultar código')}</div></article>`;}

function operationGuide(result,intent){
  const exporting=intent==='exportar';
  const specific=result.id==='consoles'||result.id==='physical-games'||result.id==='game-accessories';
  const steps=result.digital?[
    ['Define qué se entrega',result.detail,external('https://www.dian.gov.co/impuestos/Paginas/Inicio.aspx','Portal tributario DIAN')],
    ['Revisa el tratamiento tributario','Consulta los criterios de la DIAN para software, licencias y servicios digitales según las partes, el contrato y la operación. El buscador jurídico permite revisar los conceptos completos.',external('https://normograma.dian.gov.co/dian/compilacion/herramientas_busqueda.html','Consultar doctrina y normativa')],
    ['Distingue la entrega digital del soporte físico','Si también recibes un equipo, disco o cartucho, consulta esa mercancía por separado. Conserva el contrato y los comprobantes que describen la entrega.',queryButton('Videojuegos físicos','Consultar soportes físicos')]
  ]:[
    ['Precisa el producto y su clasificación',result.detail||'Reúne ficha técnica, composición, función y presentación de la mercancía. Confirma la subpartida nacional en la DIAN.',reference('arancel','Clasificación y arancel')],
    [exporting?'Revisa destino y condiciones de salida':'Consulta requisitos antes de comprar',exporting?'Define el país de destino. Revisa restricciones de exportación, vistos buenos y condiciones de ingreso en el mercado de destino con las entidades competentes.':'Con la subpartida confirmada, revisa en VUCE si aplican registros, licencias o vistos buenos. Consulta también las condiciones de la modalidad y del importador ante la DIAN.',external(exporting?'https://www.vuce.gov.co/servicios/exportaciones':vuce,exporting?'Exportaciones en VUCE':'Importaciones en VUCE')],
    [exporting?'Comprueba origen y documentos':'Revisa origen, valor y tributos',exporting?'Reúne los documentos comerciales y de transporte; revisa si tu operación necesita una prueba de origen para solicitar una preferencia en el destino.':'Consulta gravamen e IVA vigentes en el arancel, valoración aduanera y acuerdos de origen. El país desde el que compras no determina por sí solo el origen.',reference('origen','Reglas de origen')+' '+reference('valoracion','Valoración aduanera')],
    [exporting?'Prepara la salida de la mercancía':'Prepara la declaración y el ingreso',exporting?'Revisa el procedimiento, la modalidad y los servicios de exportación. Conserva el expediente de la operación.':`${specific?'Distingue una compra personal de un envío para comercializar. ':''}Consulta el procedimiento y los documentos de importación, así como la declaración anticipada cuando corresponda. No asumas que todo envío puede ingresar por mensajería.`,reference(exporting?'exportacion':'importacion',exporting?'Guía de exportación':'Guía de importación')+' '+reference('servicios','Servicios DIAN')]
  ];
  return `<div class="product-steps">${steps.map((s,i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${escape(s[0])}</summary><div><p>${escape(s[1])}</p><div class="step-sources">${s[2]}</div></div></details>`).join('')}</div>`;
}

export function productPanel(result,state,counts){
  const intent=state.view==='exportar'||(state.view==='explorar'&&/export/i.test(state.q))?'exportar':'importar';
  const name=result.name.length>100?result.name.slice(0,97)+'…':result.name;
  const unknown=result.kind==='unknown';
  const intro=result.intro||'Referencia del índice arancelario. Revisa las características de tu mercancía y las notas legales en la fuente oficial.';
  return `<div class="product-heading"><div><p class="eyebrow">CONSULTA POR PRODUCTO</p><h2 id="product-title">${escape(name)}</h2></div><span class="product-status">${unknown?'Afina tu búsqueda':result.digital?'Entrega digital':'Orientación arancelaria'}</span></div>
    <p class="product-intro">${escape(intro)}</p>
    ${result.suggestion?`<div class="product-suggestion">¿Te refieres a ${escape(result.suggestion.toLowerCase())}? ${queryButton(result.suggestedQuery,'Ver sugerencia')}</div>`:''}
    ${result.choices?`<div class="product-choices"><span>${result.id==='games'?'¿Qué producto tienes?':'También puedes precisar'}</span>${result.choices.map(([q,label])=>queryButton(q,label)).join('')}</div>`:''}
    ${result.candidates.length?`<div class="tariff-candidates">${result.candidates.slice(0,3).map(candidateCard).join('')}</div>${result.candidates.length>3?`<details class="more-candidates"><summary>Ver otras ${result.candidates.length-3} referencias coincidentes</summary><div class="tariff-candidates">${result.candidates.slice(3).map(candidateCard).join('')}</div></details>`:''}<p class="tariff-scope">${result.total>result.candidates.length?'Selección de coincidencias del índice. Afina la descripción para acotar la consulta. ':''}Posiciones candidatas, sujetas a las notas legales y a las características del producto. Base SA 2022; verifica subpartida nacional y cambios vigentes en la DIAN. ${external(source,'Fuente del índice')}</p>`:''}
    ${unknown?`<div class="product-fallback"><p>${escape(result.detail)}</p>${external(alphabet,'Buscar por nombre en la DIAN')}<div class="product-choices"><span>Prueba una consulta</span>${['Videojuegos','Celulares','Ropa','Café','Cosméticos'].map(q=>queryButton(q)).join('')}</div></div>`:''}
    <div class="product-operation"><div class="product-path"><div class="operation-heading"><h3>${result.digital?'Continúa tu consulta':'¿Qué quieres hacer con este producto?'}</h3><nav aria-label="Operación para el producto"><a href="#importar?q=${encodeURIComponent(state.q)}" class="${intent==='importar'?'selected':''}" ${intent==='importar'?'aria-current="true"':''}>Importar <span aria-hidden="true">↙</span></a><a href="#exportar?q=${encodeURIComponent(state.q)}" class="${intent==='exportar'?'selected':''}" ${intent==='exportar'?'aria-current="true"':''}>Exportar <span aria-hidden="true">↗</span></a></nav></div><p class="operation-caption">${result.digital?'Puntos de revisión para una operación digital.':`${intent==='exportar'?'Ruta de exportación':'Ruta de importación'} · ${unknown?'Comienza por identificar la mercancía.':'Abre cada paso para consultar sus fuentes.'}`}</p>${operationGuide(result,intent)}</div><aside class="product-related"><p class="eyebrow">TEMAS RELACIONADOS</p>${result.digital?external('https://normograma.dian.gov.co/dian/compilacion/herramientas_busqueda.html','Software y servicios digitales')+external('https://www.dian.gov.co/impuestos/Paginas/Inicio.aspx','Impuestos y obligaciones'):reference('arancel','Arancel y tributos')+reference('origen','Acuerdos y origen')+reference('valoracion','Valor de la mercancía')+external(vuce,'Permisos y vistos buenos')+reference('norma1165','Régimen aduanero')}<p>La consulta conserva el producto al cambiar entre importar y exportar.</p></aside></div>
    <div class="product-footnote"><span>${counts.subheadings.toLocaleString('es-CO')} subpartidas SA · ${counts.chapters} capítulos con contenido</span><a href="#fuentes">Cómo se construye esta orientación →</a></div>`;
}
